const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const countries = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017');
  const denmark = countries.filter(ee.Filter.eq('country_na', 'Denmark'));
  const geometry = denmark.geometry();

  const start2017 = '2017-07-01';
  const end2017 = '2017-07-31';
  const start2018 = '2018-07-01';
  const end2018 = '2018-07-31';

  const scale = 1000; // Use a reasonable scale to avoid memory issues for large region
  const maxPixels = 1e9;

  // 2. Helper functions
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    // Bits 10 and 11 are clouds and cirrus, respectively.
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                   .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask).divide(10000); // Scale to SR (0-1)
  }

  function addNdvi(image) {
    const ndvi = image.normalizedDifference(['B8', 'B4']).rename('NDVI');
    return image.addBands(ndvi);
  }

  // 3. Data Acquisition & Processing Function
  async function processCollection(year, startDate, endDate, geom) {
    let collection = ee.ImageCollection('COPERNICUS/S2_SR')
      .filterBounds(geom)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 70)); // Pre-filter based on metadata

    const initialSize = await collection.size().getInfo();
    if (initialSize === 0) {
      console.log(`Images for July ${year}: 0`);
      return { ndvi: null, count: 0, initialSize: 0 }; // Indicate failure to find images
    }

    collection = collection.map(maskS2clouds).map(addNdvi);

    // Create a median composite of NDVI
    const medianNdviImage = collection.select('NDVI').median();

    // Calculate valid pixel count for NDVI
    const countPixels = await medianNdviImage.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geom,
      scale: scale,
      maxPixels: maxPixels,
      bestEffort: true
    }).get('NDVI').getInfo();

    if (countPixels === 0) {
      console.log(`Images for July ${year}: ${initialSize} (Val: 0.0, Pixels: 0)`);
      return { ndvi: null, count: 0, initialSize: initialSize }; // Indicate no valid pixels after masking
    }

    // Calculate mean NDVI for the region
    const meanNdvi = await medianNdviImage.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: geom,
      scale: scale,
      maxPixels: maxPixels,
      bestEffort: true
    }).get('NDVI').getInfo();

    console.log(`Images for July ${year}: ${initialSize} (Val: ${meanNdvi !== null ? meanNdvi.toFixed(2) : 'NaN'}, Pixels: ${countPixels})`);

    return { ndvi: meanNdvi, count: countPixels, initialSize: initialSize };
  }

  // 4. Execute processing for both years
  let result2017, result2018;

  try {
    console.log('--- Processing 2017 ---');
    result2017 = await processCollection('2017', start2017, end2017, geometry);
    console.log('--- Processing 2018 ---');
    result2018 = await processCollection('2018', start2018, end2018, geometry);
  } catch (error) {
    console.log("Error during data processing:", error.message);
    console.log("D"); // General error
    return;
  }

  // 5. Validation & Final Answer
  if (result2017.initialSize === 0 || result2018.initialSize === 0) {
    console.log("C1"); // Empty collection
    return;
  }

  if (result2017.count === 0 || result2018.count === 0) {
    console.log("C2"); // No valid pixels after masking
    return;
  }

  const ndvi2017 = result2017.ndvi;
  const ndvi2018 = result2018.ndvi;

  if (ndvi2017 === null || isNaN(ndvi2017) || ndvi2018 === null || isNaN(ndvi2018)) {
    console.log("C3"); // Calculation failed (NaN or null)
    return;
  }

  console.log(`Mean NDVI July 2017: ${ndvi2017.toFixed(3)}`);
  console.log(`Mean NDVI July 2018: ${ndvi2018.toFixed(3)}`);

  // Browning means a decrease in NDVI
  if (ndvi2018 < ndvi2017) {
    console.log("A"); // Yes, vegetation browning increased
  } else {
    console.log("B"); // No, vegetation browning did not increase or decreased
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
